(458, 1, '2025-02-05 09:58:49', '2025-02-05 08:58:49', '<!-- wp:group {\"backgroundColor\":\"custom-brown\",\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\",\"justifyContent\":\"space-between\"}} -->\n<div class=\"wp-block-group has-custom-brown-background-color has-background\"><!-- wp:site-logo {\"width\":96,\"className\":\"is-style-rounded\",\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}},\"layout\":{\"selfStretch\":\"fit\",\"flexSize\":null}}} /-->\n\n<!-- wp:search {\"label\":\"\",\"showLabel\":false,\"placeholder\":\"Rechercher...\",\"buttonText\":\"Rechercher\",\"buttonUseIcon\":true,\"style\":{\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}}} /-->\n\n<!-- wp:loginout {\"style\":{\"elements\":{\"link\":{\"color\":{\"text\":\"var:preset|color|custom-light-pink\"},\":hover\":{\"color\":{\"text\":\"var:preset|color|custom-mid-brown\"}}}},\"spacing\":{\"margin\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}}} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:group {\"style\":{\"spacing\":{\"margin\":{\"top\":\"0\",\"bottom\":\"0\"},\"padding\":{\"top\":\"var:preset|spacing|10\",\"bottom\":\"var:preset|spacing|10\",\"left\":\"var:preset|spacing|10\",\"right\":\"var:preset|spacing|10\"}}},\"backgroundColor\":\"custom-red\",\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group has-custom-red-background-color has-background\" style=\"margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--10);padding-right:var(--wp--preset--spacing--10);padding-bottom:var(--wp--preset--spacing--10);padding-left:var(--wp--preset--spacing--10)\"><!-- wp:navigation {\"ref\":5,\"textColor\":\"custom-light-pink\",\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\",\"flexWrap\":\"wrap\"}} /--></div>\n<!-- /wp:group -->', 'Header', '', 'inherit', 'closed', 'closed', '', '430-revision-v1', '', '', '2025-02-05 09:58:49', '2025-02-05 08:58:49', '', 430, 'http://localhost/DicoTrav/?p=458', 0, 'revision', '', 0),
(459, 1, '2025-02-05 10:10:40', '2025-02-05 09:10:40', '<!-- wp:group {\"style\":{\"spacing\":{\"padding\":{\"top\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"right\":\"0\"},\"margin\":{\"top\":\"0\",\"bottom\":\"0\"}}},\"layout\":{\"type\":\"default\"}} -->\n<div class=\"wp-block-group\" style=\"margin-top:0;margin-bottom:0;padding-top:0;padding-right:0;padding-bottom:0;padding-left:0\"><!-- wp:shortcode -->\n[custom_carousel]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<style>\n/* Mise en page principale */\n.main-container {\n  display: flex;\n  flex-wrap: wrap;\n  width: 100%;\n  height: calc(100vh - 134px); /* Prend toute la hauteur de la fenêtre */\n}\n\n.main-container p {\n  margin: 0px !important;\n  height: 0px;\n}\n\n.left-column {\n  width: 50%;\n  height: calc(100vh - 134px); /* Prend toute la hauteur */\n}\n\n.right-column {\n  width: 50%;\n  display: flex;\n  flex-direction: column;\n}\n\n.right-column .top-image,\n.right-column .bottom-image {\n  width: 100%;\n  height : calc(50vh - 67px);\n  background-size: cover;\n  background-position: center;\n  background-repeat: no-repeat;\n  position: relative;\n  overflow: hidden;\n}\n\n/* Correction : le pseudo-élément prend bien toute la place */\n.right-column .top-image::before,\n.right-column .bottom-image::before {\n  content: \"\";\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background-image: inherit;\n  background-size: cover;\n  background-position: center;\n  background-repeat: no-repeat;\n  transition: transform 0.5s ease-in-out;\n}\n\n/* Effet de zoom fluide */\n.right-column .top-image:hover::before,\n.right-column .bottom-image:hover::before {\n  transform: scale(1.1);\n}\n\n.overlay {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: rgba(0, 0, 0, 0.5);\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  color: #fff;\n  font-size: 1.2em;\n  transition: font-size 0.5s ease;\n}\n\n.overlay:hover {\n  font-size: 1.5em;\n}\n\n/* Carousel */\n.carousel-container {\n  position: relative;\n  overflow: hidden;\n  height: calc(100vh - 134px);\n  width: 100%;\n}\n\n.carousel-item {\n  position: absolute;\n  width: 100%;\n  top: 0;\n  left: 0;\n}\n\n.carousel-image {\n  width: 100%;\n  height: calc(100vh - 134px);\n  background-size: cover;\n  background-position: center;\n  background-repeat: no-repeat;\n  position: relative;\n  overflow: hidden;\n  transition: transform 0.5s ease-in-out;\n}\n\n/* Effet de zoom sur le carousel */\n.carousel-image:hover {\n  transform: scale(1.1);\n}\n\n/* Mode responsive pour les écrans inférieurs à 768px */\n@media (max-width: 768px) {\n  .main-container {\n    flex-direction: column;\n    height: auto;\n  }\n\n.carousel-image{\nheight : calc(50vh - 134px)\n}\n\n  .carousel-container {\n    order: 1;\n    height: calc(50vh - 134px); /* Ajustement pour mobile */\n  }\n\n  .left-column {\n    order: 2;\n    width: 100%;\n    height: calc(50vh - 134px);\n  }\n\n  .right-column {\n    order: 3;\n    width: 100%;\n    flex-direction: column;\n  }\n\n  .right-column .top-image,\n  .right-column .bottom-image {\n    height : calc(50vh - 134px);\n  }\n}\n</style>\n<!-- /wp:html --></div>\n<!-- /wp:group -->', 'Loop', '', 'publish', 'closed', 'closed', '', 'loop', '', '', '2025-04-03 20:24:40', '2025-04-03 18:24:40', '', 0, 'http://localhost/DicoTrav/index.php/loop/', 0, 'wp_template_part', '', 0),
