(592, 1, '2025-02-08 12:36:02', '2025-02-08 11:36:02', '<!-- wp:group {\"layout\":{\"type\":\"flex\",\"flexWrap\":\"nowrap\"}} -->\n<div class=\"wp-block-group\"><!-- wp:shortcode -->\n[lien_admin_auteur]\n<!-- /wp:shortcode -->\n\n<!-- wp:navigation {\"ref\":1045,\"overlayMenu\":\"never\"} /--></div>\n<!-- /wp:group -->\n\n<!-- wp:um-block/um-account {\"tab\":\"all\"} /-->\n\n<!-- wp:group {\"layout\":{\"type\":\"constrained\"}} -->\n<div class=\"wp-block-group\"><!-- wp:buttons {\"layout\":{\"type\":\"flex\",\"justifyContent\":\"center\"}} -->\n<div class=\"wp-block-buttons\"><!-- wp:button {\"className\":\"disco-btn\"} -->\n<div class=\"wp-block-button disco-btn\"><a class=\"wp-block-button__link wp-element-button\" href=\"http://localhost/DicoTrav/index.php/logout\">Se déconnecter</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:group -->\n\n<!-- wp:html -->\n<style>\n\n.um-account-main label, .um-account-heading{\n  color: #29354C !important;\n}\n\n/* Style pour le lien actif du compte */\n.um-account-link.current{\n  background-color: #29354C !important;\n  color: #F7F1EB !important;\n  padding: 0.5em 1em !important;\n  transition: background-color 0.3s !important;\n}\n\n.um-account-nav{\n  padding: 0 !important;\n}\n\n.um-account-nav a.current {\n  background-color: #29354C !important;\n  color: #F7F1EB !important;\n  transition: background-color 0.3s !important;\n}\n\n.um-account-link, .um-account-nav{\n  background-color: #3c5075 !important;\n  color: #F7F1EB !important;\n  transition: background-color 0.3s !important;\n}\n\n/* Style pour les boutons */\n.um-button, .um-request-button {\n  background-color: #29354C !important;\n  color: #F7F1EB !important;\n  border: none !important;\n  transition: background-color 0.3s !important;\n}\n\n.um-button {\n  padding: 1em !important;\n}\n.um-request-button{\n  padding: 0.5em 1em !important;\n}\n\n/* Effet hover pour le lien actif et les boutons */\n.um-button:hover, .um-request-button:hover, .disco-btn a:hover {\n  background-color: #3c5075 !important;\n}\n\n.um-account-link:hover{\n  background-color: #29354C !important;\n}\n\n.um-account-title, .um-account-arrow, .um-account-icon {\n  color: #F7F1EB !important;\n}\n\n@media screen and (min-width: 565px) {\n  .um-account-link, .um-account-nav{\n    padding: 0.5em 1em !important;\n  }\n}\n\n.disco-btn a{\n  background-color: #29354C !important;\n  color: #F7F1EB !important;\n  border: none !important;\n  transition: background-color 0.3s !important;\n  border-radius: 5px;\n  padding: 0.5em 1em !important;\n}\n\n.um-form{\n  border-radius: 20px;\n  background: #00000020 !important;\n  padding: 20px;\n}\n\n</style>\n<!-- /wp:html -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Compte', '', 'publish', 'closed', 'closed', '', 'compte', '', '', '2025-03-20 12:21:16', '2025-03-20 11:21:16', '', 0, 'http://localhost/DicoTrav/index.php/account/', 10, 'page', '', 0),
