n-left: 250px !important;\\n        width: calc(100% - 250px) !important;\\n    }\\nheader{z-index:101 !important;}\\n}\\n\\n:where(.wp-site-blocks) > * {\\n    margin-block-start: 0;\\n    margin-block-end: 0;\\n}\\n\\nHeader\\n{position:fixed;\\nMin-width: 100%;\\nz-index:100;\\nMargin-bottom : 134px! important;\\n}\\n\\nFooter\\n{\\nposition:relative;\\nz-index:100 !important;\\n}\\n\\n\\n\"},\"settings\":{\"typography\":{\"fontFamilies\":{\"theme\":[{\"fontFace\":[{\"fontFamily\":\"PT Serif\",\"fontStretch\":\"normal\",\"fontStyle\":\"normal\",\"fontWeight\":\"400\",\"src\":[\"file:.\\/assets\\/fonts\\/pt-serif\\/pt-serif-v17-latin-regular.woff2\"]},{\"fontFamily\":\"PT Serif\",\"fontStretch\":\"normal\",\"fontStyle\":\"italic\",\"fontWeight\":\"500\",\"src\":[\"file:.\\/assets\\/fonts\\/pt-serif\\/pt-serif-v17-latin-italic.woff2\"]},{\"fontFamily\":\"PT Serif\",\"fontStretch\":\"normal\",\"fontStyle\":\"normal\",\"fontWeight\":\"700\",\"src\":[\"file:.\\/assets\\/fonts\\/pt-serif\\/pt-serif-v17-latin-700.woff2\"]},{\"fontFamily\":\"PT Serif\",\"fontStretch\":\"normal\",\"fontStyle\":\"italic\",\"fontWeight\":\"700\",\"src\":[\"file:.\\/assets\\/fonts\\/pt-serif\\/pt-serif-v17-latin-700italic.woff2\"]}],\"fontFamily\":\"\\\"PT Serif\\\", ui-serif, Georgia, serif\",\"name\":\"PT Serif\",\"slug\":\"pt-serif\"},{\"fontFamily\":\"ui-sans-serif, -apple-system, BlinkMacSystemFont, \\\"Segoe UI\\\", Roboto, \\\"Helvetica Neue\\\", sans-serif\",\"name\":\"System Sans Serif\",\"slug\":\"system-sans-serif\"},{\"fontFamily\":\"ui-serif, Georgia, serif\",\"name\":\"System Serif\",\"slug\":\"system-serif\"},{\"fontFamily\":\"ui-monospace, Menlo, Consolas, Monaco, \\\"Liberation Mono\\\", \\\"Lucida Console\\\", monospace\",\"name\":\"System Monospace\",\"slug\":\"system-monospace\"}],\"custom\":[{\"name\":\"EB Garamond\",\"slug\":\"eb-garamond\",\"fontFamily\":\"\\\"EB Garamond\\\", serif\",\"fontFace\":[{\"src\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/uploads\\/fon