(754, 1, '2025-02-26 09:32:34', '2025-02-26 08:32:34', '<!-- wp:html -->\n    <div class=\"timeline\">\n        <div class=\"timeline-item\">\n            <div class=\"timeline-content\">\n                <h2>Moyen Âge</h2>\n                <p>Période allant du Ve siècle au XVe siècle.</p>\n            </div>\n        </div>\n        <div class=\"timeline-item\">\n            <div class=\"timeline-content\">\n                <h2>Époque Moderne</h2>\n                <p>Période allant du XVIe au XVIIIe siècle.</p>\n            </div>\n        </div>\n        <div class=\"timeline-item\">\n            <div class=\"timeline-content\">\n                <h2 class=\"contempo\">Époque <br> <br> Contemporaine</h2>\n                <p>Période allant du XIXe siècle à nos jours.</p>\n            </div>\n        </div>\n    </div>\n\n    <style>\n       .timeline {\n            position: relative;\n            max-width: 600px;\n            margin: auto;\n        }\n\n        .timeline::after {\n            content: \'\';\n            position: absolute;\n            width: 4px;\n            background-color: #333;\n            top: 0;\n            bottom: 0;\n            left: 50%;\n            transform: translateX(-50%);\n        }\n\n        .timeline-item {\n            position: relative;\n            background-color: inherit;\n            width: 50%;\n            padding: 10px 20px;\n            box-sizing: border-box;\n        }\n\n        .timeline-item:nth-child(odd) {\n            left: 0;\n            text-align: right;\n        }\n\n        .timeline-item:nth-child(even) {\n            left: 50%;\n        }\n\n        .timeline-content {\n            background: #fff;\n            padding: 15px;\n            border-radius: 5px;\n            box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);\n            position: relative;\n            margin-bottom: 50px;\n        }\n\n        .timeline-item::before {\n            content: \'\';\n            position: absolute;\n            top: 15px;\n            width: 20px;\n            height: 20px;\n            background-color: #333;\n            border-radius: 50%;\n            left: 50%;\n            transform: translateX(-50%);\n        }\n\n        h2 {\n            font-size: 18px;\n            margin-bottom: 8px;\n        }\n        .contempo{\n            font-size: 16px;\n        }\n    </style>\n<!-- /wp:html -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Frise', '', 'inherit', 'closed', 'closed', '', '750-revision-v1', '', '', '2025-02-26 09:32:34', '2025-02-26 08:32:34', '', 750, 'http://localhost/DicoTrav/?p=754', 0, 'revision', '', 0),
