(761, 1, '2025-02-26 09:54:33', '2025-02-26 08:54:33', '<!-- wp:columns -->\n<div class=\"wp-block-columns\"><!-- wp:column -->\n<div class=\"wp-block-column\"><!-- wp:heading -->\n<h2 class=\"wp-block-heading\">Dernières publications</h2>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {\"height\":\"55px\"} -->\n<div style=\"height:55px\" aria-hidden=\"true\" class=\"wp-block-spacer\"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:latest-posts {\"postsToShow\":3,\"postLayout\":\"grid\",\"displayFeaturedImage\":true,\"featuredImageSizeSlug\":\"large\",\"addLinkToFeaturedImage\":true} /-->\n\n<!-- wp:shortcode -->\n[custom_carousel]\n<!-- /wp:shortcode -->\n\n<!-- wp:html -->\n<style>\n/* Mise en page principale */\n.main-container {\n  display: flex;\n  width: 100%;\n}\n\n.left-column {\n  width: 50%;\n}\n\n.right-column {\n  width: 50%;\n  display: flex;\n  flex-direction: column;\n}\n\n.right-column .top-image,\n.right-column .bottom-image {\n  width: 100%;\n  height: 50vh; /* ou 50% selon vos besoins */\n  background-size: cover;\n  background-position: center;\n}\n\n/* Carousel et images */\n.carousel-container {\n  position: relative;\n  overflow: hidden;\n}\n\n.carousel-item {\n  position: absolute;\n  width: 100%;\n  top: 0;\n  left: 0;\n}\n\n.carousel-image {\n  width: 100%;\n  height: 400px; /* ajustez la hauteur selon vos besoins */\n  background-size: cover;\n  background-position: center;\n  position: relative;\n}\n\n/* Overlay noir */\n.carousel-image .overlay {\n  position: absolute;\n  top: 0;\n  left: 0;\n  width: 100%;\n  height: 100%;\n  background: rgba(0, 0, 0, 0.5);\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  color: #fff;\n  font-size: 1.2em;\n}\n</style>\n<!-- /wp:html --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Loop', '', 'inherit', 'closed', 'closed', '', '459-revision-v1', '', '', '2025-02-26 09:54:33', '2025-02-26 08:54:33', '', 459, 'http://localhost/DicoTrav/?p=761', 0, 'revision', '', 0),
