ebarOverlay {\n    display: none;\n    position: fixed;\n    top: 0;\n    left: 0;\n    min-width: 100vw;\n    min-height: 100vh;\n    background: rgba(0, 0, 0, 0.5);\n    z-index: 100;\n    opacity: 0;\n    margin-block-start: -1.5rem !important;\n}\n\n/* Bouton pour ouvrir la sidebar (flèche) */\n.sidebar-toggle {\n    position: fixed;\n    top: 50%;\n    left: 12px;\n    transform: translateX(-2px);\n    z-index: 201;\n    background: #29354C;\n    color: #F7F1EB;\n    border: none;\n    padding: 10px 15px;\n    font-size: 1.5rem;\n    cursor: pointer;\n    transition: transform 0.3s ease;\n    border-radius: 5px;\n}\n\n.sidebar-toggle:hover {\n    transform: translateX(2px);\n}\n\n/* Bouton de fermeture (croix) */\n.sidebar-close {\n    position: absolute;\n    top: 0px;\n    right: 10px;\n    background: none;\n    border: none;\n    color: #F7F1EB;\n    font-size: 3rem;\n    cursor: pointer;\n    transition: transform 0.3s ease, scale 0.2s ease;\n}\n\n.sidebar-close:hover {\n    transform: scale(1.2);\n    color: #FF0000;\n}\n\n/* Styles spécifiques pour desktop (>=768px) */\n@media screen and (min-width: 768px) {\n    /* La sidebar est toujours visible */\n    #sidebar {\n        transform: none;\n        opacity: 1;\n        padding: 20px !important;\n        top: 134px !important;\n    }\n    /* Masquer le bouton d\'ouverture, le bouton de fermeture et l\'overlay */\n    #openSidebar,\n    .sidebar-close,\n    #sidebarOverlay {\n        display: none;\n    }\n}\n\n#sidebar nav ul {\n    list-style: none;\n    padding: 0;\n    margin: 0;\n}\n\n#sidebar nav ul li {\n    margin: 1rem 0;\n}\n\n#sidebar nav ul li a {\n    color: #F7F1EB;\n    text-decoration: none;\n    display: block;\n    padding: 3px;\n    font-size: 1.1rem;\n    background: #3c5075;\n    text-align: center;\n    border-radius: 5px;\n    transition: background-color 0.3s ease, transform 0.2s ease;\n}\n\n#sidebar nav ul li a:hover {\n    transform: translateX(5px);\n}\n\n/* Couleurs spécifique