INSERT INTO `wp_rcb_template` (`id`, `identifier`, `context`, `type`, `version`, `created_at`, `headline`, `sub_headline`, `logo_url`, `is_outdated`, `is_disabled`, `is_invalidate_needed`, `is_untranslated`, `is_hidden`, `is_recommended`, `is_cloud`, `tier`, `tags`, `before_middleware`, `after_middleware`, `other_meta`, `successor_of_identifiers`, `machine_translation_status`) VALUES
(1, 'real-cookie-banner', 'fr_FR', 'service', 2, '2023-02-06 07:47:00', 'Real Cookie Banner', '', 'http://localhost/DicoTrav/wp-content/plugins/real-cookie-banner/public/images/logos/real-cookie-banner.svg', 0, 0, 0, 0, 1, 0, 0, 'free', '{}', '{\"isCdn\":false,\"isProviderCurrentWebsite\":true,\"provider\":\"\",\"providerContact\":{},\"providerNotice\":\"\",\"providerLegalNoticeUrl\":\"\",\"providerPrivacyPolicyUrl\":\"\",\"technicalDefinitions\":[{\"type\":\"http\",\"name\":\"real_cookie_banner*\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Identifiant unique pour le consentement, mais pas pour le visiteur du site web. Hachure de r\\u00e9vision pour les param\\u00e8tres de la banni\\u00e8re des cookies (textes, couleurs, caract\\u00e9ristiques, groupes de services, services, bloqueurs de contenu, etc.) ID des services et groupes de services autoris\\u00e9s.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Consentements recueillis dans le cadre du TCF et stock\\u00e9s dans le format TC String, y compris les fournisseurs du TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements relatifs aux types de consentement (finalit\\u00e9s) collect\\u00e9s dans le cadre du mode de consentement de Google sont stock\\u00e9s pour tous les services compatibles avec le mode de consentement de Google.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner-test\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Cookie mis en place pour tester la fonctionnalit\\u00e9 des cookies HTTP. Il est supprim\\u00e9 imm\\u00e9diatement apr\\u00e8s le test.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Identifiant unique pour le consentement, mais pas pour le visiteur du site web. Hachure de r\\u00e9vision pour les param\\u00e8tres de la banni\\u00e8re des cookies (textes, couleurs, caract\\u00e9ristiques, groupes de services, services, bloqueurs de contenu, etc.) Identifiant des services et des groupes de services autoris\\u00e9s. N\'est stock\\u00e9 que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements recueillis dans le cadre du TCF sont stock\\u00e9s dans le format TC String, y compris les fournisseurs du TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales. Ils ne sont stock\\u00e9s que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements recueillis dans le cadre du mode de consentement de Google sont stock\\u00e9s dans les types de consentement (finalit\\u00e9s) pour tous les services compatibles avec le mode de consentement de Google. Il n\'est stock\\u00e9 que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner-consent-queue*\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Mise en cache locale de la s\\u00e9lection dans une banni\\u00e8re de cookies jusqu\'\\u00e0 ce que le serveur documente le consentement ; documentation p\\u00e9riodique ou tentative de changement de page si le serveur n\'est pas disponible ou surcharg\\u00e9.\"}],\"shouldUncheckContentBlockerCheckbox\":false,\"shouldUncheckContentBlockerCheckboxWhenOneOf\":[],\"executePriority\":10,\"codeOptIn\":\"\",\"codeOptOut\":\"\",\"codeOnPageLoad\":\"\",\"tagManagerOptInEventName\":\"\",\"tagManagerOptOutEventName\":\"\",\"executeCodeOptInWhenNoTagManagerConsentIsGiven\":false,\"executeCodeOptOutWhenNoTagManagerConsentIsGiven\":false,\"deleteTechnicalDefinitionsAfterOptOut\":false,\"dynamicFields\":[],\"dataProcessingInCountries\":[],\"dataProcessingInCountriesSpecialTreatments\":[],\"sccConclusionInstructionsNotice\":\"\",\"googleConsentModeConsentTypes\":[],\"isEmbeddingOnlyExternalResources\":false,\"legalBasis\":\"legal-requirement\",\"legalBasisNotice\":\"\",\"purpose\":\"Real Cookie Banner demande aux visiteurs du site web leur consentement pour installer des cookies et traiter des donn\\u00e9es personnelles. A cette fin, un UUID (identification pseudonyme de l\'utilisateur) est attribu\\u00e9 \\u00e0 chaque visiteur du site web, qui est valable jusqu\'\\u00e0 l\'expiration du cookie pour m\\u00e9moriser le consentement. Les cookies sont utilis\\u00e9s pour tester si les cookies peuvent \\u00eatre install\\u00e9s, pour stocker la r\\u00e9f\\u00e9rence au consentement document\\u00e9, pour stocker quels services de quels groupes de services le visiteur a consenti, et, si le consentement est obtenu dans le cadre de \'Transparency & Consent Framework\' (TCF), pour stocker le consentement dans les partenaires TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales. Dans le cadre de l\'obligation de divulgation conform\\u00e9ment au RGPD, le consentement recueilli est enti\\u00e8rement document\\u00e9. Cela inclut, outre les services et groupes de services auxquels le visiteur a consenti, et si le consentement est obtenu conform\\u00e9ment \\u00e0 la norme TCF, \\u00e0 quels partenaires TCF, finalit\\u00e9s et caract\\u00e9ristiques le visiteur a consenti, tous les param\\u00e8tres de la banni\\u00e8re de cookies au moment du consentement ainsi que les circonstances techniques (par exemple, la taille de la zone affich\\u00e9e au moment du consentement) et les interactions de l\'utilisateur (par exemple, cliquer sur des boutons) qui ont conduit au consentement. Le consentement est recueilli une fois par langue.\",\"group\":\"essential\",\"technicalHandlingNotice\":\"\",\"createContentBlockerNotice\":\"\",\"groupNotice\":\"\",\"language\":null,\"name\":\"Real Cookie Banner\",\"headline\":\"Real Cookie Banner\",\"subHeadline\":\"\",\"id\":0,\"identifier\":\"real-cookie-banner\",\"version\":2,\"successorOfIdentifierInfo\":[],\"enabledWhenOneOf\":[],\"isHidden\":true,\"recommendedWhenOneOf\":[],\"extendsIdentifier\":null,\"status\":\"published\",\"createdAt\":\"2023-02-06T07:47:00+00:00\",\"tier\":\"free\",\"logoUrl\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/plugins\\/real-cookie-banner\\/public\\/images\\/logos\\/real-cookie-banner.svg\",\"machineTranslationStatus\":\"no-translation\",\"consumerData\":{\"tags\":[],\"isUntranslated\":false}}', '{\"isCdn\":false,\"isProviderCurrentWebsite\":true,\"provider\":\"\",\"providerContact\":{},\"providerNotice\":\"\",\"providerLegalNoticeUrl\":\"\",\"providerPrivacyPolicyUrl\":\"\",\"technicalDefinitions\":[{\"type\":\"http\",\"name\":\"real_cookie_banner*\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Identifiant unique pour le consentement, mais pas pour le visiteur du site web. Hachure de r\\u00e9vision pour les param\\u00e8tres de la banni\\u00e8re des cookies (textes, couleurs, caract\\u00e9ristiques, groupes de services, services, bloqueurs de contenu, etc.) ID des services et groupes de services autoris\\u00e9s.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Consentements recueillis dans le cadre du TCF et stock\\u00e9s dans le format TC String, y compris les fournisseurs du TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements relatifs aux types de consentement (finalit\\u00e9s) collect\\u00e9s dans le cadre du mode de consentement de Google sont stock\\u00e9s pour tous les services compatibles avec le mode de consentement de Google.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner-test\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Cookie mis en place pour tester la fonctionnalit\\u00e9 des cookies HTTP. Il est supprim\\u00e9 imm\\u00e9diatement apr\\u00e8s le test.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Identifiant unique pour le consentement, mais pas pour le visiteur du site web. Hachure de r\\u00e9vision pour les param\\u00e8tres de la banni\\u00e8re des cookies (textes, couleurs, caract\\u00e9ristiques, groupes de services, services, bloqueurs de contenu, etc.) Identifiant des services et des groupes de services autoris\\u00e9s. N\'est stock\\u00e9 que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements recueillis dans le cadre du TCF sont stock\\u00e9s dans le format TC String, y compris les fournisseurs du TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales. Ils ne sont stock\\u00e9s que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Les consentements recueillis dans le cadre du mode de consentement de Google sont stock\\u00e9s dans les types de consentement (finalit\\u00e9s) pour tous les services compatibles avec le mode de consentement de Google. Il n\'est stock\\u00e9 que jusqu\'\\u00e0 ce que le consentement soit document\\u00e9 sur le serveur du site web.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner-consent-queue*\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Mise en cache locale de la s\\u00e9lection dans une banni\\u00e8re de cookies jusqu\'\\u00e0 ce que le serveur documente le consentement ; documentation p\\u00e9riodique ou tentative de changement de page si le serveur n\'est pas disponible ou surcharg\\u00e9.\"}],\"shouldUncheckContentBlockerCheckbox\":false,\"shouldUncheckContentBlockerCheckboxWhenOneOf\":[],\"executePriority\":10,\"codeOptIn\":\"\",\"codeOptOut\":\"\",\"codeOnPageLoad\":\"\",\"tagManagerOptInEventName\":\"\",\"tagManagerOptOutEventName\":\"\",\"executeCodeOptInWhenNoTagManagerConsentIsGiven\":false,\"executeCodeOptOutWhenNoTagManagerConsentIsGiven\":false,\"deleteTechnicalDefinitionsAfterOptOut\":false,\"dynamicFields\":[],\"dataProcessingInCountries\":[],\"dataProcessingInCountriesSpecialTreatments\":[],\"sccConclusionInstructionsNotice\":\"\",\"googleConsentModeConsentTypes\":[],\"isEmbeddingOnlyExternalResources\":false,\"legalBasis\":\"legal-requirement\",\"legalBasisNotice\":\"\",\"purpose\":\"Real Cookie Banner demande aux visiteurs du site web leur consentement pour installer des cookies et traiter des donn\\u00e9es personnelles. A cette fin, un UUID (identification pseudonyme de l\'utilisateur) est attribu\\u00e9 \\u00e0 chaque visiteur du site web, qui est valable jusqu\'\\u00e0 l\'expiration du cookie pour m\\u00e9moriser le consentement. Les cookies sont utilis\\u00e9s pour tester si les cookies peuvent \\u00eatre install\\u00e9s, pour stocker la r\\u00e9f\\u00e9rence au consentement document\\u00e9, pour stocker quels services de quels groupes de services le visiteur a consenti, et, si le consentement est obtenu dans le cadre de \'Transparency & Consent Framework\' (TCF), pour stocker le consentement dans les partenaires TCF, les objectifs, les objectifs sp\\u00e9ciaux, les caract\\u00e9ristiques et les caract\\u00e9ristiques sp\\u00e9ciales. Dans le cadre de l\'obligation de divulgation conform\\u00e9ment au RGPD, le consentement recueilli est enti\\u00e8rement document\\u00e9. Cela inclut, outre les services et groupes de services auxquels le visiteur a consenti, et si le consentement est obtenu conform\\u00e9ment \\u00e0 la norme TCF, \\u00e0 quels partenaires TCF, finalit\\u00e9s et caract\\u00e9ristiques le visiteur a consenti, tous les param\\u00e8tres de la banni\\u00e8re de cookies au moment du consentement ainsi que les circonstances techniques (par exemple, la taille de la zone affich\\u00e9e au moment du consentement) et les interactions de l\'utilisateur (par exemple, cliquer sur des boutons) qui ont conduit au consentement. Le consentement est recueilli une fois par langue.\",\"group\":\"essential\",\"technicalHandlingNotice\":\"\",\"createContentBlockerNotice\":\"\",\"groupNotice\":\"\",\"language\":null,\"name\":\"Real Cookie Banner\",\"headline\":\"Real Cookie Banner\",\"subHeadline\":\"\",\"id\":0,\"identifier\":\"real-cookie-banner\",\"version\":2,\"successorOfIdentifierInfo\":[],\"enabledWhenOneOf\":[],\"isHidden\":true,\"recommendedWhenOneOf\":[],\"extendsIdentifier\":null,\"status\":\"published\",\"createdAt\":\"2023-02-06T07:47:00+00:00\",\"tier\":\"free\",\"logoUrl\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/plugins\\/real-cookie-banner\\/public\\/images\\/logos\\/real-cookie-banner.svg\",\"machineTranslationStatus\":\"no-translation\",\"consumerData\":{\"tags\":[],\"isUntranslated\":false,\"isDisabled\":false,\"isRecommended\":false,\"contentBlockerTemplates\":[]}}', '{\"extendsIdentifier\":null}', NULL, 'no-translation'),
(2, 'real-cookie-banner', 'en_US', 'service', 2, '2023-02-06 07:47:00', 'Real Cookie Banner', '', 'http://localhost/DicoTrav/wp-content/plugins/real-cookie-banner/public/images/logos/real-cookie-banner.svg', 0, 0, 0, 0, 1, 0, 0, 'free', '{}', '{\"isCdn\":false,\"isProviderCurrentWebsite\":true,\"provider\":\"\",\"providerContact\":{},\"providerNotice\":\"\",\"providerLegalNoticeUrl\":\"\",\"providerPrivacyPolicyUrl\":\"\",\"technicalDefinitions\":[{\"type\":\"http\",\"name\":\"real_cookie_banner*\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Unique identifier for the consent, but not for the website visitor. Revision hash for settings of cookie banner (texts, colors, features, service groups, services, content blockers etc.). IDs for consented services and service groups.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Consents collected under TCF stored in TC String format, including TCF vendors, purposes, special purposes, features, and special features.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Consents into consent types (purposes)  collected under Google Consent Mode stored for all Google Consent Mode compatible services.\"},{\"type\":\"http\",\"name\":\"real_cookie_banner-test\",\"host\":\"main+subdomains\",\"duration\":365,\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Cookie set to test HTTP cookie functionality. Deleted immediately after test.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Unique identifier for the consent, but not for the website visitor. Revision hash for settings of cookie banner (texts, colors, features, service groups, services, content blockers etc.). IDs for consented services and service groups. Is only stored until consent is documented on the website server.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-tcf\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Consents collected under TCF stored in TC String format, including TCF vendors, purposes, special purposes, features, and special features. Is only stored until consent is documented on the website server.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner*-gcm\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Consents collected under Google Consent Mode stored in consent types (purposes) for all Google Consent Mode compatible services. Is only stored until consent is documented on the website server.\"},{\"type\":\"local\",\"name\":\"real_cookie_banner-consent-queue*\",\"host\":\"current+protocol\",\"duration\":\"1\",\"durationUnit\":\"d\",\"isSessionDuration\":false,\"purpose\":\"Local caching of selection in cookie banner until server documents consent; documentation periodic or at page switches attempted if server is unavailable or overloaded.\"}],\"shouldUncheckContentBlockerCheckbox\":false,\"shouldUncheckContentBlockerCheckboxWhenOneOf\":[],\"executePriority\":10,\"codeOptIn\":\"\",\"codeOptOut\":\"\",\"codeOnPageLoad\":\"\",\"tagManagerOptInEventName\":\"\",\"tagManagerOptOutEventName\":\"\",\"executeCodeOptInWhenNoTagManagerConsentIsGiven\":false,\"executeCodeOptOutWhenNoTagManagerConsentIsGiven\":false,\"deleteTechnicalDefinitionsAfterOptOut\":false,\"dynamicFields\":[],\"dataProcessingInCountries\":[],\"dataProcessingInCountriesSpecialTreatments\":[],\"sccConclusionInstructionsNotice\":\"\",\"googleConsentModeConsentTypes\":[],\"isEmbeddingOnlyExternalResources\":false,\"legalBasis\":\"legal-requirement\",\"legalBasisNotice\":\"\",\"purpose\":\"Real Cookie Banner asks website visitors for consent to set cookies and process personal data. For this purpose, a UUID (pseudonymous identification of the user) is assigned to each website visitor, which is valid until the cookie expires to store the consent. Cookies are used to test whether cookies can be set, to store reference to documented consent, to store which services from which service groups the visitor has consented to, and, if consent is obtained under the Transparency & Consent Framework (TCF), to store consent in TCF partners, purposes, special purposes, features and special features. As part of the obligation to disclose according to GDPR, the collected consent is fully documented. This includes, in addition to the services and service groups to which the visitor has consented, and if consent is obtained according to the TCF standard, to which TCF partners, purposes and features the visitor has consented, all cookie banner settings at the time of consent as well as the technical circumstances (e.g. size of the displayed area at the time of consent) and the user interactions (e.g. clicking on buttons) that led to consent. Consent is collected once per language.\",\"group\":\"essential\",\"technicalHandlingNotice\":\"\",\"createContentBlockerNotice\":\"\",\"groupNotice\":\"\",\"language\":null,\"name\":\"Real Cookie Banner\",\"headline\":\"Real Cookie Banner\",\"subHeadline\":\"\",\"id\":0,\"identifier\":\"real-cookie-banner\",\"version\":2,\"successorOfIdentifierInfo\":[],\"enabledWhenOneOf\":[],\"isHidden\":true,\"recommendedWhenOneOf\":[],\"extendsIdentifier\":null,\"status\":\"published\",\"createdAt\":\"2023-02-06T07:47:00+00:00\",\"tier\":\"free\",\"logoUrl\":\"http:\\/\\/localhost\\/DicoTrav\\/wp-content\\/plugins\\/real-cookie-banner\\/public\\/images\\/logos\\/real-cookie-banner.svg\",\"machineTranslationStatus\":\"no-translation\",\"consumerData\":{\"tags\":[],\"isUntranslated\":false}}', '{\"isCdn\":false,\"isProviderCurrentWebsite\":tr