(1033, 'Exclude Headings', 'Exclure les titrages', 'easy-table-of-contents', 2, 1033, 0),
(1034, 'Specify headings to be excluded from appearing in the table of contents. Separate multiple headings with a pipe', '', 'easy-table-of-contents', 0, 1034, 0),
(1035, ' Use an asterisk ', '', 'easy-table-of-contents', 0, 1035, 0),
(1036, 'as a wildcard to match other text.', '', 'easy-table-of-contents', 0, 1036, 0),
(1037, 'Examples:', 'Exemples :', 'easy-table-of-contents', 2, 1037, 0),
(1038, 'Fruit*', '', 'easy-table-of-contents', 0, 1038, 0),
