(1041, 'Ignore headings with \"Fruit Diet\" somewhere in the heading.', '', 'easy-table-of-contents', 0, 1041, 0),
(1042, 'Apple Tree|Oranges|Yellow Bananas', '', 'easy-table-of-contents', 0, 1042, 0),
(1043, 'Ignore headings that are exactly \"Apple Tree\", \"Oranges\" or \"Yellow Bananas\".', '', 'easy-table-of-contents', 0, 1043, 0),
(1044, 'Note:', '', 'easy-table-of-contents', 0, 1044, 0),
(1045, 'This is not case sensitive', '', 'easy-table-of-contents', 0, 1045, 0),
