(1885, 'The text that is used for primary button text.', 'Texte utilisé pour le bouton primaire.', 'ultimate-member', 2, 1885, 0),
(1886, 'Registration Secondary Button', 'Bouton secondaire de la page d’inscription', 'ultimate-member', 2, 1886, 0),
(1887, 'Show Registration Secondary Button', 'Afficher un bouton secondaire sur la page d’inscription', 'ultimate-member', 2, 1887, 0),
(1888, 'Registration Secondary Button Text', 'Texte du bouton secondaire de la page d’inscription', 'ultimate-member', 2, 1888, 0),
(1889, 'The text that is used for the secondary button text.', 'Texte utilisé pour le bouton secondaire.', 'ultimate-member', 2, 1889, 0),
(1890, 'Registration Secondary Button URL', 'URL du bouton secondaire de la page d’inscription', 'ultimate-member', 2, 1890, 0),
(1891, 'You can replace default link for this button by entering custom URL.', 'Vous pouvez remplacer le lien par défaut de ce bouton en saisissant une URL personnalisée.', 'ultimate-member', 2, 1891, 0),
(1892, 'Registration Field Icons', 'Icônes des champs d’inscription', 'ultimate-member', 2, 1892, 0),
(1893, 'This controls the display of field icons in the registration form.', 'Cette option permet de contrôler l’affichage des icônes de champ dans le formulaire d’inscription.', 'ultimate-member', 2, 1893, 0),
(1894, 'Login Form', 'Formulaire de connexion', 'ultimate-member', 2, 1894, 0),
(1895, 'This section allows you to customize the user login template and size.', 'Cette section vous permet de personnaliser le modèle et la taille de la fenêtre de connexion du compte.', 'ultimate-member', 2, 1895, 0),
(1896, 'Login Default Template', 'Modèle de connexion par défaut', 'ultimate-member', 2, 1896, 0),
(1897, 'This will be the default template to output login.', 'Il s’agit du modèle par défaut pour le formulaire de connexion.', 'ultimate-member', 2, 1897, 0),
(1898, 'Login Maximum Width', 'Largeur maximale du formulaire de connexion', 'ultimate-member', 2, 1898, 0);
